    [60199] = {"祝福圣水", "魔法制造的物品\n需要等级 50\n使用：对 5 码范围内的亡灵造成 397 到 514 点神圣伤害。", "EpochHead 消耗品", "consumable", { ["Conjured Item"] = "魔法制造的物品", ["Requires Level 50"] = "需要等级 50", ["Use: Inflicts 397 to 514 Holy damage to Undead in a 5 yard radius."] = "使用：对 5 码范围内的亡灵造成 397 到 514 点神圣伤害。" }, "Blessed Holy Water"},
    [60423] = {"压倒性力量合剂", "需要等级 50\n使用：Increases melee和ranged 攻击强度 by 90 for 2小时. Counts as both a Battle和Guardian elixir. This 效果 persists through death.（3秒冷却）", "EpochHead 消耗品", "consumable", { ["Requires Level 50"] = "需要等级 50", ["Use: Increases melee and ranged attack power by 90 for 2 hrs. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)"] = "使用：Increases melee和ranged 攻击强度 by 90 for 2小时. Counts as both a Battle和Guardian elixir. This 效果 persists through death.（3秒冷却）" }, "Flask of Overwhelming Might"},
    [60626] = {"黑咖啡", "需要等级 15\n使用：Sobers you up a little. \"A warning on the side reads: Contents are HOT! Do not pour on self or others.\"。", "EpochHead 消耗品", "consumable", { ["Requires Level 15"] = "需要等级 15", ["Use: Sobers you up a little. \"A warning on the side reads: Contents are HOT! Do not pour on self or others.\""] = "使用：Sobers you up a little. \"A warning on the side reads: Contents are HOT! Do not pour on self or others.\"。" }, "Black Coffee"},
    [60628] = {"Crestfall 蟹肉玉米卷", "需要等级 45\n使用：在 30秒 内恢复 2148 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果：受到伤害时有几率使你身后敌人的攻击强度降低 127 点，持续 10秒。该充分进食效果持续 15分钟。", "EpochHead 消耗品", "consumable", { ["Requires Level 45"] = "需要等级 45", ["Use: Restores 2148 health over 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain a chance upon taking damage to reduce the attack power of enemies behind you by 127 for 10 sec. Lasts 15 min."] = "使用：在 30秒 内恢复 2148 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果：受到伤害时有几率使你身后敌人的攻击强度降低 127 点，持续 10秒。该充分进食效果持续 15分钟。" }, "Crestfall Crab Taco"},
    [60630] = {"龙虾卷", "需要等级 45\n使用：在 30秒 内恢复 2148 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，使你的法术和技能治疗效果提高 12 点，持续 15分钟。", "EpochHead 消耗品", "consumable", { ["Requires Level 45"] = "需要等级 45", ["Use: Restores 2148 health over 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and increase your healing done by spells and abilities by 12 for 15 min."] = "使用：在 30秒 内恢复 2148 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，使你的法术和技能治疗效果提高 12 点，持续 15分钟。" }, "Lobster Roll"},
    [60632] = {"科赞橙", "使用：在 18秒 内恢复 61 点生命值。进食时必须保持坐姿。", "EpochHead 消耗品", "consumable", { ["Use: Restores 61 health over 18 sec. Must remain seated while eating."] = "使用：在 18秒 内恢复 61 点生命值。进食时必须保持坐姿。" }, "Kezan Orange"},
    [60633] = {"海员大饮", "使用：An extremely potent alcoholic beverage.（10秒冷却）", "EpochHead 消耗品", "consumable", { ["Use: An extremely potent alcoholic beverage. (10 Sec Cooldown)"] = "使用：An extremely potent alcoholic beverage.（10秒冷却）" }, "Seafarer's Swig"},
    [60712] = {"多兰纳尔茶", "使用：在 21秒 内恢复 436 点法力值。饮用时必须保持坐姿。（1分钟冷却）", "EpochHead 消耗品", "consumable", { ["Use: Restores 436 mana over 21 sec. Must remain seated while drinking. (1 Min Cooldown)"] = "使用：在 21秒 内恢复 436 点法力值。饮用时必须保持坐姿。（1分钟冷却）" }, "Dolanaar Tea"},
    [60746] = {"艾露恩之石", "拾取后绑定\n使用：为目标武器施加艾露恩的祝福，使攻击强度提高 15 点、法术强度提高 10 点。持续 30分钟。（1秒冷却）", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Use: Applies a blessing of Elune to the target weapon, increasing attack power by 15 and spell power by 10. Lasts for 30 Minutes. (1 Sec Cooldown)"] = "使用：为目标武器施加艾露恩的祝福，使攻击强度提高 15 点、法术强度提高 10 点。持续 30分钟。（1秒冷却）" }, "Stone of Elune"},
    [60755] = {"小型袖珍卫士", "拾取后绑定\n唯一（20）\n需要等级 30\n使用：Summon a miniature 法力值 elemental to aid you in combat for 10分钟.（10分钟冷却）", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique (20)"] = "唯一（20）", ["Requires Level 30"] = "需要等级 30", ["Use: Summon a miniature mana elemental to aid you in combat for 10 minutes. (10 Min Cooldown)"] = "使用：Summon a miniature 法力值 elemental to aid you in combat for 10分钟.（10分钟冷却）" }, "Minor Pocket Guardian"},
    [60757] = {"巨龙灵魂石", "拾取后绑定\n\"A faint crackling emanates from the stone.\"", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定" }, "Grombolar Soulstone"},
    [60759] = {"篝火草案", "拾取后绑定\n唯一（5）\n需要等级 50\n使用：使你受到灾火影响，每层灾火都会灼烧你。受到近战伤害时有几率灼烧攻击者，并按双方拥有的灾火层数造成伤害。持续 15分钟。（2分钟冷却）\n\"It burns!\"", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique (5)"] = "唯一（5）", ["Requires Level 50"] = "需要等级 50", ["Use: Afflicts you with Balefire, burning you for each stack you have. Melee damage taken has a chance to burn attackers, causing damage for every stack of Balefire you both have. Lasts 15 min. (2 Min Cooldown)"] = "使用：使你受到灾火影响，每层灾火都会灼烧你。受到近战伤害时有几率灼烧攻击者，并按双方拥有的灾火层数造成伤害。持续 15分钟。（2分钟冷却）" }, "Balefire Draught"},
    [60761] = {"邪石烈酒", "需要等级 45\n使用：Increases fire和暗影抗性 by 5. An incredibly strong alcoholic beverage.", "EpochHead 消耗品", "consumable", { ["Requires Level 45"] = "需要等级 45", ["Use: Increases fire and shadow resistance by 5. An incredibly strong alcoholic beverage."] = "使用：Increases fire和暗影抗性 by 5. An incredibly strong alcoholic beverage." }, "Felstone Grog"},
    [60763] = {"痛苦雕文", "使用：将你身上的灾火诅咒转移给一个敌方目标。只能在诅咒之地使用。（10秒冷却）\n\"The rune makes you feel uneasy...\"", "EpochHead 消耗品", "consumable", { ["Use: Transfers the Balefire curse from you to an enemy target. Only usable in the Blasted Lands. (10 Sec Cooldown)"] = "使用：将你身上的灾火诅咒转移给一个敌方目标。只能在诅咒之地使用。（10秒冷却）" }, "Glyph of Affliction"},
    [60764] = {"否定雕文", "使用：驱散一个友方目标身上的灾火诅咒。（10秒冷却）\n\"The rune changes shape upon each inspection.\"", "EpochHead 消耗品", "consumable", { ["Use: Dispels the Balefire curse from a friendly target. (10 Sec Cooldown)"] = "使用：驱散一个友方目标身上的灾火诅咒。（10秒冷却）" }, "Glyph of Negation"},
    [60772] = {"可疑炖菜", "需要等级 35\n使用：在 30秒 内恢复 1392 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，12 耐力和精神，持续 15分钟。\"Is that a finger?\"", "EpochHead 消耗品", "consumable", { ["Requires Level 35"] = "需要等级 35", ["Use: Restores 1392 health over 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 12 Stamina and Spirit for 15 min. \"Is that a finger?\""] = "使用：在 30秒 内恢复 1392 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，12 耐力和精神，持续 15分钟。\"Is that a finger?\"" }, "Suspicious Stew"},
    [60786] = {"星光宝石", "需要等级 45\n使用：Increases 玩家的 最大 生命值 by 250 for 20分钟. Counts as a 守护药剂.", "EpochHead 消耗品", "consumable", { ["Requires Level 45"] = "需要等级 45", ["Use: Increases the player's maximum health by 250 for 20 min. Counts as a Guardian Elixir."] = "使用：Increases 玩家的 最大 生命值 by 250 for 20分钟. Counts as a 守护药剂." }, "Starlight Gem"},
