    [62082] = {"瘟疫药水", "需要等级 7\n使用：Cures up to 4 疾病效果.（2分钟冷却）", "EpochHead 消耗品", "consumable", { ["Requires Level 7"] = "需要等级 7", ["Use: Cures up to 4 diseases. (2 Min Cooldown)"] = "使用：Cures up to 4 疾病效果.（2分钟冷却）" }, "Potion of Plagueward"},
    [62096] = {"铜带扣", "拾取后绑定\n使用：灌注你的腰带，永久性地使所有主属性提高 1 点。只能灌注锻造师的腰带，灌注后会使腰带变为灵魂绑定。（1秒冷却）", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Use: Infuse your belt, permanently increasing all primary stats by 1. Only the Blacksmith's belt can be infused, and infusing a belt will cause it to become soulbound. (1 Sec Cooldown)"] = "使用：灌注你的腰带，永久性地使所有主属性提高 1 点。只能灌注锻造师的腰带，灌注后会使腰带变为灵魂绑定。（1秒冷却）" }, "Copper Belt Buckle"},
