    [62133] = {"蛋白质奶昔", "需要等级 45\n使用：在 30秒 内恢复 1806 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，6 力量，持续 15分钟。", "EpochHead 消耗品", "consumable", { ["Requires Level 45"] = "需要等级 45", ["Use: Restores 1806 health over 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 6 Strength for 15 min."] = "使用：在 30秒 内恢复 1806 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，6 力量，持续 15分钟。" }, "Protein Shake"},
