    [70001] = {"老化镐升级底座", "拾取后绑定\n唯一\n需要等级 55\n使用：升级黑铁镐的底座和说明。上面写着你需要 20 块黑铁锭和 4 块奥金锭，为燃烧精华制作外壳和导流脉络。不需要锻造技能，但需要黑熔炉。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Requires Level 55"] = "需要等级 55", ["Use: Base and instructions for upgrading a Dark Iron Pick, it says you will need 20 Dark Iron Bars and 4 Arcanite Bars to build a housing and channeling vein for a Burning Essence. Smithing not required, however a Black Forge is."] = "使用：升级黑铁镐的底座和说明。上面写着你需要 20 块黑铁锭和 4 块奥金锭，为燃烧精华制作外壳和导流脉络。不需要锻造技能，但需要黑熔炉。" }, "Aged Pick Upgrade Base"},
    [90071] = {"吉利吉姆地雷", "吉利吉姆岛\n拾取后绑定\n唯一\n持续时间：7分钟\n使用：在地上放置一枚地雷。当敌对生物经过附近时，地雷会爆炸，造成 394 到 506 点火焰伤害并将其击退。地雷持续 2分钟。\"看起来足够稳定……？\"", "EpochHead 消耗品", "consumable", { ["Gillijim's Isle"] = "吉利吉姆岛", ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Duration: 7 min"] = "持续时间：7分钟", ["Use: Places a Land Mine on the ground. When a hostile creature passes near, It will explode for 394 to 506 fire damage and knock them away. The mine has a duration of 2 min. \"Looks stable enough...?\""] = "使用：在地上放置一枚地雷。当敌对生物经过附近时，地雷会爆炸，造成 394 到 506 点火焰伤害并将其击退。地雷持续 2分钟。\"看起来足够稳定……？\"" }, "Gillijim Land Mine"},
    [90072] = {"龙语空灵酊剂", "拾取后绑定\n唯一\n需要等级 60\n使用：Negates 80% of all spell 伤害 for 5秒. \"Simply holding this flask makes you feel empty.\"。", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Requires Level 60"] = "需要等级 60", ["Use: Negates 80% of all spell damage for 5 sec. \"Simply holding this flask makes you feel empty.\""] = "使用：Negates 80% of all spell 伤害 for 5秒. \"Simply holding this flask makes you feel empty.\"。" }, "Draconic Null Tincture"},
    [90075] = {"蜂蜜黄油面包", "拾取后绑定\n需要等级 55\n使用：在 30秒 内恢复 2550 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，15 所有抗性，持续 6分钟。\"好吃到你根本不想和任何人分享。\"", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Requires Level 55"] = "需要等级 55", ["Use: Restores 2550 health over 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 15 All Resistances for 6 minutes. \"So good you don't even want to share it with anyone.\""] = "使用：在 30秒 内恢复 2550 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，15 所有抗性，持续 6分钟。\"好吃到你根本不想和任何人分享。\"" }, "Honey Butter Bread"},
    [90076] = {"EZ-Thro“炸弹”", "吉利吉姆岛\n拾取后绑定\n唯一\n持续时间：4分钟\n使用：造成 132 到 218 点火焰伤害，并击退那个不幸的受害者……不管最后是谁。\"EZ-Thro 总部品质监控。\"", "EpochHead 消耗品", "consumable", { ["Gillijim's Isle"] = "吉利吉姆岛", ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Duration: 4 min"] = "持续时间：4分钟", ["Use: Inflicts 132 to 218 Fire damage and knocks the unfortunate victim away... Whoever that ends up being. \"Quality controlled at EZ-Thro headquarters.\""] = "使用：造成 132 到 218 点火焰伤害，并击退那个不幸的受害者……不管最后是谁。\"EZ-Thro 总部品质监控。\"" }, "EZ-Thro \"Da Bomba\""},
    [90082] = {"维克图斯权杖", "拾取后绑定\n唯一\n使用：Channel into the skull of the blue dragon in Azure Rest to drag his 精神 out of the nether.", "EpochHead 消耗品", "consumable", { ["Binds when picked up"] = "拾取后绑定", ["Unique"] = "唯一", ["Use: Channel into the skull of the blue dragon in Azure Rest to drag his spirit out of the nether."] = "使用：Channel into the skull of the blue dragon in Azure Rest to drag his 精神 out of the nether." }, "Scepter of Vectus"},
    [90089] = {"魔脉碎片", "\"这种稀有材料几乎因残存的奥术能量而震颤。\"", "EpochHead 消耗品", "consumable", { ["\"This rare ingredient is practically shaking with remnant arcane energy.\""] = "\"这种稀有材料几乎因残存的奥术能量而震颤。\"" }, "Leyline Shard"},
