    [90515] = {"强效熔岩之吻", "需要等级 45\n使用：在 30秒 内恢复 1392 点生命值。进食时必须保持坐姿。", "EpochHead 消耗品", "consumable", { ["Requires Level 45"] = "需要等级 45", ["Use: Restores 1392 health over 30 sec. Must remain seated while eating."] = "使用：在 30秒 内恢复 1392 点生命值。进食时必须保持坐姿。" }, "Greater Lava Kisser"},
    [90520] = {"抗火药水", "需要等级 32\n使用：使resistance to Fire提高 65 点，持续 3分钟。（2分钟冷却）", "EpochHead 消耗品", "consumable", { ["Requires Level 32"] = "需要等级 32", ["Use: Increases your resistance to Fire by 65 for 3 min. (2 Min Cooldown)"] = "使用：使resistance to Fire提高 65 点，持续 3分钟。（2分钟冷却）" }, "Fire Resistance Potion"},
    [90531] = {"烟熏熔岩之吻", "需要等级 55\n使用：在 30秒 内恢复 4410 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，移动速度提高 6%，但每 3秒 受到 125 点火焰伤害。持续 15分钟。", "EpochHead 消耗品", "consumable", { ["Requires Level 55"] = "需要等级 55", ["Use: Restores 4410 health over 30 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 6% movement speed and you will take 125 Fire damage every 3 seconds. Lasts 15 min."] = "使用：在 30秒 内恢复 4410 点生命值。进食时必须保持坐姿。如果进食至少 10 秒，你会获得充分进食效果，移动速度提高 6%，但每 3秒 受到 125 点火焰伤害。持续 15分钟。" }, "Smoked Lava Kisser"},
    [100000] = {"外观转化药水", "账号绑定\n需要等级 10\n使用：一饮而尽！（2分钟冷却）\n\"同时允许改名，每个角色最多两次。\"", "EpochHead 消耗品", "consumable", { ["Binds to account"] = "账号绑定", ["Requires Level 10"] = "需要等级 10", ["Use: Drink up! (2 Min Cooldown)"] = "使用：一饮而尽！（2分钟冷却）", ["\"Also allows to change your name, limited to two times per character.\""] = "\"同时允许改名，每个角色最多两次。\"" }, "Appearance Transmutation Potion"},
    [100001] = {"种族转化药水", "账号绑定\n需要等级 10\n使用：一饮而尽！（2分钟冷却）\n\"不会改变你的种族技能，种族技能由种族知识系统控制。\"", "EpochHead 消耗品", "consumable", { ["Binds to account"] = "账号绑定", ["Requires Level 10"] = "需要等级 10", ["Use: Drink up! (2 Min Cooldown)"] = "使用：一饮而尽！（2分钟冷却）", ["\"Does not change your racials, that is controlled by the Racial Knowledge system.\""] = "\"不会改变你的种族技能，种族技能由种族知识系统控制。\"" }, "Race Transmutation Potion"},
    [100002] = {"阵营转化药水", "账号绑定\n需要等级 10\n使用：一饮而尽！（2分钟冷却）\n\"你的任务日志和部分声望会被清空，不会改变你的种族技能。\"", "EpochHead 消耗品", "consumable", { ["Binds to account"] = "账号绑定", ["Requires Level 10"] = "需要等级 10", ["Use: Drink up! (2 Min Cooldown)"] = "使用：一饮而尽！（2分钟冷却）", ["\"Your quest log and some reputations will be wiped, does not change your racials. \""] = "\"你的任务日志和部分声望会被清空，不会改变你的种族技能。\"" }, "Faction Transmutation Potion"},
    [100003] = {"密封标题卷轴", "账号绑定\n使用：This Sealed Title grants you \"Of Epoch\" Title.（1分钟冷却）", "EpochHead 消耗品", "consumable", { ["Binds to account"] = "账号绑定", ["Use: This Sealed Title grants you \"Of Epoch\" Title. (1 Min Cooldown)"] = "使用：This Sealed Title grants you \"Of Epoch\" Title.（1分钟冷却）" }, "Sealed Title Scroll"},
